-- ============================================================================
-- 🛡️ SECURITY FIXES: HANDOFF CODES + RLS HARDENING + INVITE TOKEN RATE LIMIT
-- Copyright (c) 2026 ApexMissions. All rights reserved.
--
-- 1) handoff_codes table: single-use, time-bounded, user+target-subdomain bound
-- 2) SET search_path = '' on ALL SECURITY DEFINER functions (fully qualified)
-- 3) Confirm REVOKE FROM PUBLIC/anon on all RPCs
-- 4) Invite tokens: enforce min entropy (generated by app, not user), rate limit lookup
-- 5) Remove demo seed from production path; remove demo fallback in RPC
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1) HANDOFF CODES TABLE
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.handoff_codes (
  code_hash bytea PRIMARY KEY,           -- SHA-256 hash of the code
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  target_slug text NOT NULL,             -- company slug or 'platform'
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,       -- 60 seconds from creation
  consumed_at timestamptz,               -- NULL until consumed
  CONSTRAINT handoff_codes_expires_future CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS handoff_codes_user_created_idx
  ON public.handoff_codes (user_id, created_at DESC);

-- RLS: only the owning user can read their own unconsumed codes (for debugging)
ALTER TABLE public.handoff_codes ENABLE ROW LEVEL SECURITY;

GRANT SELECT ON public.handoff_codes TO authenticated;
GRANT INSERT ON public.handoff_codes TO authenticated;
GRANT ALL ON public.handoff_codes TO service_role;

DROP POLICY IF EXISTS "Users can view their own handoff codes" ON public.handoff_codes;
CREATE POLICY "Users can view their own handoff codes"
  ON public.handoff_codes
  FOR SELECT TO authenticated
  USING (user_id = auth.uid());

DROP POLICY IF EXISTS "Users can insert handoff codes for themselves" ON public.handoff_codes;
CREATE POLICY "Users can insert handoff codes for themselves"
  ON public.handoff_codes
  FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid());

-- ----------------------------------------------------------------------------
-- 2) RPC: issue_handoff_code(target_slug) -> returns plaintext code (once)
--     SECURITY DEFINER, search_path = '', stores only hash
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.issue_handoff_code(p_target_slug text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_code text;
  v_code_hash bytea;
  v_expires timestamptz := now() + interval '60 seconds';
  v_slug text := lower(btrim(coalesce(p_target_slug, '')));
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  -- Validate target slug format (DNS label or 'platform')
  IF v_slug <> 'platform' AND v_slug !~ '^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$' THEN
    RAISE EXCEPTION 'Invalid target slug';
  END IF;

  -- Generate 128-bit (16 byte) random code, encode as URL-safe base64 (22 chars)
  v_code := encode(gen_random_bytes(16), 'base64url');
  v_code_hash := digest(v_code, 'sha256');

  INSERT INTO public.handoff_codes (code_hash, user_id, target_slug, expires_at)
  VALUES (v_code_hash, v_uid, v_slug, v_expires);

  RETURN v_code;  -- Only time the plaintext is returned
END;
$$;

REVOKE EXECUTE ON FUNCTION public.issue_handoff_code(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.issue_handoff_code(text) TO authenticated;

-- ----------------------------------------------------------------------------
-- 3) RPC: consume_handoff_code(code) -> returns target_slug on success
--     SECURITY DEFINER, search_path = '', single-use, time-bounded
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.consume_handoff_code(p_code text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_code_hash bytea := digest(p_code, 'sha256');
  v_row public.handoff_codes%ROWTYPE;
BEGIN
  SELECT * INTO v_row
  FROM public.handoff_codes
  WHERE code_hash = v_code_hash
  FOR UPDATE SKIP LOCKED;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invalid or expired handoff code';
  END IF;

  IF v_row.consumed_at IS NOT NULL THEN
    RAISE EXCEPTION 'Handoff code already used';
  END IF;

  IF v_row.expires_at <= now() THEN
    RAISE EXCEPTION 'Handoff code expired';
  END IF;

  -- Verify the code belongs to the current authenticated user
  IF v_row.user_id <> auth.uid() THEN
    RAISE EXCEPTION 'Invalid or expired handoff code';
  END IF;

  UPDATE public.handoff_codes
  SET consumed_at = now()
  WHERE code_hash = v_code_hash;

  RETURN v_row.target_slug;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.consume_handoff_code(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.consume_handoff_code(text) TO authenticated;

