-- accept_company_invite (add SET search_path = '')
DROP FUNCTION IF EXISTS public.accept_company_invite(text);
CREATE OR REPLACE FUNCTION public.accept_company_invite(p_invite_token text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_company_id uuid;
BEGIN
  SELECT c.id INTO v_company_id
  FROM public.companies c
  WHERE c.invite_token = p_invite_token;

  IF v_company_id IS NULL THEN
    RAISE EXCEPTION 'Invalid or expired invite token';
  END IF;

  UPDATE public.profiles
  SET company_id = v_company_id,
      updated_at = now()
  WHERE id = auth.uid();

  UPDATE public.tasks
  SET company_id = v_company_id
  WHERE user_id = auth.uid()
    AND company_id IS NULL;

  RETURN v_company_id;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.accept_company_invite(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.accept_company_invite(text) TO authenticated;

