-- ----------------------------------------------------------------------------
-- 5) INVITE TOKEN ENTROPY: companies.invite_token must be 128+ bits (22+ base64url)
--    Add constraint and update index
-- ----------------------------------------------------------------------------
ALTER TABLE public.companies
  DROP CONSTRAINT IF EXISTS companies_invite_token_entropy_check;

ALTER TABLE public.companies
  ADD CONSTRAINT companies_invite_token_entropy_check
  CHECK (length(invite_token) >= 22 AND invite_token ~ '^[A-Za-z0-9_-]+$');

-- ----------------------------------------------------------------------------
-- 6) RATE LIMIT RPC FOR INVITE LOOKUPS (consumed by get_company_route_by_invite_token)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.consume_rate_limit(p_key text, p_limit integer, p_window_seconds integer)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_now timestamptz := now();
  v_window_start timestamptz := v_now - (p_window_seconds || ' seconds')::interval;
  v_count bigint;
BEGIN
  DELETE FROM public.rate_limit_buckets
  WHERE window_start < v_window_start;

  INSERT INTO public.rate_limit_buckets (key, window_start, count)
  VALUES (p_key, v_window_start, 1)
  ON CONFLICT (key, window_start) DO UPDATE
    SET count = rate_limit_buckets.count + 1
  RETURNING count INTO v_count;

  RETURN v_count <= p_limit;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.consume_rate_limit(text, integer, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.consume_rate_limit(text, integer, integer) TO authenticated;

-- Rate limit buckets table (if not exists)
CREATE TABLE IF NOT EXISTS public.rate_limit_buckets (
  key text NOT NULL,
  window_start timestamptz NOT NULL,
  count bigint NOT NULL DEFAULT 1,
  PRIMARY KEY (key, window_start)
);

ALTER TABLE public.rate_limit_buckets ENABLE ROW LEVEL SECURITY;

